metric(s,'Mutual inductance',g.M*1e6,'μH');metric(s,'Primary current',I,'A');metric(s,'Linked flux per secondary turn',g.M*I/p.N2*1e6,'μWb');metric(s,'Secondary emf',emf*1000,'mV');metric(s,'Secondary current',I2*1000,'mA');
